import json, sys, time, urllib.request, urllib.error

BASE = "http://localhost:8080"
token = None
log = []

def get_token():
    global token
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req) as r:
        token = json.load(r)["token"]

def request(path, auth=True):
    attempts = 0
    while True:
        attempts += 1
        if attempts > 50:
            raise RuntimeError("too many attempts on " + path)
        headers = {}
        if auth:
            if token is None:
                get_token()
            headers["Authorization"] = "Bearer " + token
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "replace")
            log.append((path, e.code, body[:200], e.headers.get("Retry-After")))
            if e.code == 401:
                get_token()
                continue
            if e.code == 429 or e.code >= 500:
                wait = e.headers.get("Retry-After")
                try:
                    delay = float(wait) if wait is not None else 1.0
                except ValueError:
                    delay = 1.0
                time.sleep(delay)
                continue
            if e.code == 404 and auth is True and path.startswith("/customers/"):
                return None
            raise
        except (urllib.error.URLError, ConnectionError, TimeoutError) as e:
            log.append((path, "net", str(e)[:200], None))
            time.sleep(1.0)
            continue

def main():
    pages = []
    page = 1
    total = None
    while True:
        data = request("/orders?page=%d" % page)
        pages.append(data)
        total = data["total_pages"]
        if data.get("next") is None or page >= total:
            break
        page += 1
    items = [o for p in pages for o in p["items"]]
    customers = {}
    cids = sorted({o["customer_id"] for o in items})
    for cid in cids:
        customers[cid] = request("/customers/" + cid)
    json.dump({"pages": len(pages), "total_pages": total, "items": items,
               "customers": customers}, open("/tmp/recon/raw.json", "w"))
    print("pages fetched:", len(pages), "total_pages:", total)
    print("items:", len(items), "distinct ids:", len({o["id"] for o in items}))
    print("customers:", len(customers), "missing:", sum(1 for v in customers.values() if v is None))
    print("retry/error events:", len(log))
    for entry in log[:20]:
        print(entry)

if __name__ == "__main__":
    main()

